import{_ as t,o as a,c as o,U as d}from"./index-DyBTC7Sp.js";const r={},s={class:"legal-doc"};function i(n,e){return a(),o("div",s,[...e[0]||(e[0]=[d('<h1 data-v-ed48e36d>COOKIE POLICY</h1><p class="subtitle" data-v-ed48e36d><strong data-v-ed48e36d>Last updated</strong> April 05, 2026</p><p data-v-ed48e36d> This Cookie Policy explains how <strong data-v-ed48e36d>Aidan Boissonneault</strong> (&quot;Company,&quot; &quot;we,&quot; &quot;us,&quot; and &quot;our&quot;) uses cookies and similar technologies to recognize you when you visit our website at <a href="https://www.tervabrewed.com" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>https://www.tervabrewed.com</a> (&quot;Website&quot;). It explains what these technologies are and why we use them, as well as your rights to control our use of them. </p><p data-v-ed48e36d> In some cases we may use cookies to collect personal information, or that becomes personal information if we combine it with other information. </p><h2 data-v-ed48e36d>What are cookies?</h2><p data-v-ed48e36d> Cookies are small data files that are placed on your computer or mobile device when you visit a website. Cookies are widely used by website owners in order to make their websites work, or to work more efficiently, as well as to provide reporting information. </p><p data-v-ed48e36d> Cookies set by the website owner (in this case, Aidan Boissonneault) are called &quot;first-party cookies.&quot; Cookies set by parties other than the website owner are called &quot;third-party cookies.&quot; Third-party cookies enable third-party features or functionality to be provided on or through the website (e.g., advertising, interactive content, and analytics). The parties that set these third-party cookies can recognize your computer both when it visits the website in question and also when it visits certain other websites. </p><h2 data-v-ed48e36d>Why do we use cookies?</h2><p data-v-ed48e36d> We use first- and third-party cookies for several reasons. Some cookies are required for technical reasons in order for our Website to operate, and we refer to these as &quot;essential&quot; or &quot;strictly necessary&quot; cookies. Other cookies also enable us to track and target the interests of our users to enhance the experience on our Online Properties. Third parties serve cookies through our Website for advertising, analytics, and other purposes. This is described in more detail below. </p><h2 data-v-ed48e36d>How can I control cookies?</h2><p data-v-ed48e36d> You have the right to decide whether to accept or reject cookies. You can exercise your cookie rights by setting your preferences in the Cookie Preference Center. The Cookie Preference Center allows you to select which categories of cookies you accept or reject. Essential cookies cannot be rejected as they are strictly necessary to provide you with services. </p><p data-v-ed48e36d> The Cookie Preference Center can be found in the notification banner and on our Website. If you choose to reject cookies, you may still use our Website though your access to some functionality and areas of our Website may be restricted. You may also set or amend your web browser controls to accept or refuse cookies. </p><p data-v-ed48e36d> The specific types of first- and third-party cookies served through our Website and the purposes they perform are described in the table below (please note that the specific cookies served may vary depending on the specific Online Properties you visit): </p><h3 data-v-ed48e36d>Analytics and customization cookies</h3><p data-v-ed48e36d>These cookies collect information that is used either in aggregate form to help us understand how our Website is being used or how effective our marketing campaigns are, or to help us customize our Website for you.</p><div class="cookie-table" data-v-ed48e36d><table data-v-ed48e36d><tbody data-v-ed48e36d><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Name:</td><td class="value" data-v-ed48e36d>_ga_#</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Purpose:</td><td class="value" data-v-ed48e36d>Used to distinguish individual users by means of designation of a randomly generated number as client identifier, which allows calculation of visits and sessions</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Provider:</td><td class="value" data-v-ed48e36d>.tervabrewed.com</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Service:</td><td class="value" data-v-ed48e36d>Google Analytics - <a href="https://business.safety.google/privacy/" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>View Service Privacy Policy</a></td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Type:</td><td class="value" data-v-ed48e36d>http_cookie</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Expires in:</td><td class="value" data-v-ed48e36d>~400 days</td></tr></tbody></table></div><div class="cookie-table" data-v-ed48e36d><table data-v-ed48e36d><tbody data-v-ed48e36d><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Name:</td><td class="value" data-v-ed48e36d>_ga</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Purpose:</td><td class="value" data-v-ed48e36d>Records a particular ID used to come up with data about website usage by the user</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Provider:</td><td class="value" data-v-ed48e36d>.tervabrewed.com</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Service:</td><td class="value" data-v-ed48e36d>Google Analytics - <a href="https://business.safety.google/privacy/" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>View Service Privacy Policy</a></td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Type:</td><td class="value" data-v-ed48e36d>http_cookie</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Expires in:</td><td class="value" data-v-ed48e36d>~400 days</td></tr></tbody></table></div><div class="cookie-table" data-v-ed48e36d><table data-v-ed48e36d><tbody data-v-ed48e36d><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Name:</td><td class="value" data-v-ed48e36d>_gat#</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Purpose:</td><td class="value" data-v-ed48e36d>Enables Google Analytics to regulate the rate of requesting. It is a HTTP cookie type that lasts for a session.</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Provider:</td><td class="value" data-v-ed48e36d>.tervabrewed.com</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Service:</td><td class="value" data-v-ed48e36d>Google Analytics - <a href="https://business.safety.google/privacy/" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>View Service Privacy Policy</a></td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Type:</td><td class="value" data-v-ed48e36d>http_cookie</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Expires in:</td><td class="value" data-v-ed48e36d>1 minute</td></tr></tbody></table></div><div class="cookie-table" data-v-ed48e36d><table data-v-ed48e36d><tbody data-v-ed48e36d><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Name:</td><td class="value" data-v-ed48e36d>_gid</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Purpose:</td><td class="value" data-v-ed48e36d>Keeps an entry of unique ID which is then used to come up with statistical data on website usage by visitors. It is a HTTP cookie type and expires after a browsing session.</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Provider:</td><td class="value" data-v-ed48e36d>.tervabrewed.com</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Service:</td><td class="value" data-v-ed48e36d>Google Analytics - <a href="https://business.safety.google/privacy/" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>View Service Privacy Policy</a></td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Type:</td><td class="value" data-v-ed48e36d>http_cookie</td></tr><tr data-v-ed48e36d><td class="label" data-v-ed48e36d>Expires in:</td><td class="value" data-v-ed48e36d>24 hours</td></tr></tbody></table></div><h2 data-v-ed48e36d>How can I control cookies on my browser?</h2><p data-v-ed48e36d> As the means by which you can refuse cookies through your web browser controls vary from browser to browser, you should visit your browser&#39;s help menu for more information. The following is information about how to manage cookies on the most popular browsers: </p><ul data-v-ed48e36d><li data-v-ed48e36d><a href="https://support.google.com/chrome/answer/95647#zippy=%2Callow-or-block-cookies" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Chrome</a></li><li data-v-ed48e36d><a href="https://support.microsoft.com/en-us/windows/delete-and-manage-cookies-168dab11-0753-043d-7c16-ede5947fc64d" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Internet Explorer</a></li><li data-v-ed48e36d><a href="https://support.mozilla.org/en-US/kb/enhanced-tracking-protection-firefox-desktop?redirectslug=enable-and-disable-cookies-website-preferences&amp;redirectlocale=en-US" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Firefox</a></li><li data-v-ed48e36d><a href="https://support.apple.com/en-ie/guide/safari/sfri11471/mac" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Safari</a></li><li data-v-ed48e36d><a href="https://support.microsoft.com/en-us/windows/microsoft-edge-browsing-data-and-privacy-bb8174ba-9d73-dcf2-9b4a-c582b4e640dd" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Edge</a></li><li data-v-ed48e36d><a href="https://help.opera.com/en/latest/web-preferences/" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Opera</a></li></ul><p data-v-ed48e36d>In addition, most advertising networks offer you a way to opt out of targeted advertising. If you would like to find out more information, please visit:</p><ul data-v-ed48e36d><li data-v-ed48e36d><a href="http://www.aboutads.info/choices/" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Digital Advertising Alliance</a></li><li data-v-ed48e36d><a href="https://youradchoices.ca/" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Digital Advertising Alliance of Canada</a></li><li data-v-ed48e36d><a href="http://www.youronlinechoices.com/" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>European Interactive Digital Advertising Alliance</a></li></ul><h2 data-v-ed48e36d>What about other tracking technologies, like web beacons?</h2><p data-v-ed48e36d> Cookies are not the only way to recognize or track visitors to a website. We may use other, similar technologies from time to time, like web beacons (sometimes called &quot;tracking pixels&quot; or &quot;clear gifs&quot;). These are tiny graphics files that contain a unique identifier that enables us to recognize when someone has visited our Website or opened an email including them. This allows us, for example, to monitor the traffic patterns of users from one page within a website to another, to deliver or communicate with cookies, to understand whether you have come to the website from an online advertisement displayed on a third-party website, to improve site performance, and to measure the success of email marketing campaigns. In many instances, these technologies are reliant on cookies to function properly, and so declining cookies will impair their functioning. </p><h2 data-v-ed48e36d>Do you use Flash cookies or Local Shared Objects?</h2><p data-v-ed48e36d> Websites may also use so-called &quot;Flash Cookies&quot; (also known as Local Shared Objects or &quot;LSOs&quot;) to, among other things, collect and store information about your use of our services, fraud prevention, and for other site operations. </p><p data-v-ed48e36d> If you do not want Flash Cookies stored on your computer, you can adjust the settings of your Flash player to block Flash Cookies storage using the tools contained in the <a href="http://www.macromedia.com/support/documentation/en/flashplayer/help/settings_manager07.html" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Website Storage Settings Panel</a>. You can also control Flash Cookies by going to the <a href="http://www.macromedia.com/support/documentation/en/flashplayer/help/settings_manager03.html" target="_blank" rel="noopener noreferrer" data-v-ed48e36d>Global Storage Settings Panel</a> and following the instructions (which may include instructions that explain, for example, how to delete existing Flash Cookies, how to prevent Flash LSOs from being placed on your computer without your being asked, and (for Flash Player 8 and later) how to block Flash Cookies that are not being delivered by the operator of the page you are on at the time). </p><p data-v-ed48e36d> Please note that setting the Flash Player to restrict or limit acceptance of Flash Cookies may reduce or impede the functionality of some Flash applications, including, potentially, Flash applications used in connection with our services or online content. </p><h2 data-v-ed48e36d>Do you serve targeted advertising?</h2><p data-v-ed48e36d> Third parties may serve cookies on your computer or mobile device to serve advertising through our Website. These companies may use information about your visits to this and other websites in order to provide relevant advertisements about goods and services that you may be interested in. They may also employ technology that is used to measure the effectiveness of advertisements. They can accomplish this by using cookies or web beacons to collect information about your visits to this and other sites in order to provide relevant advertisements about goods and services of potential interest to you. The information collected through this process does not enable us or them to identify your name, contact details, or other details that directly identify you unless you choose to provide these. </p><h2 data-v-ed48e36d>How often will you update this Cookie Policy?</h2><p data-v-ed48e36d> We may update this Cookie Policy from time to time in order to reflect, for example, changes to the cookies we use or for other operational, legal, or regulatory reasons. Please therefore revisit this Cookie Policy regularly to stay informed about our use of cookies and related technologies. </p><p data-v-ed48e36d>The date at the top of this Cookie Policy indicates when it was last updated.</p><h2 data-v-ed48e36d>Where can I get further information?</h2><p data-v-ed48e36d> If you have any questions about our use of cookies or other technologies, please email us at <a href="mailto:tervabrewed@gmail.com" data-v-ed48e36d>tervabrewed@gmail.com</a> or by post to: </p><div class="contact-block" data-v-ed48e36d><p data-v-ed48e36d><strong data-v-ed48e36d>Aidan Boissonneault</strong></p><p data-v-ed48e36d>North Bay, Ontario</p><p data-v-ed48e36d>Canada</p></div><p class="generated-by" data-v-ed48e36d> This Cookie Policy was created using <a href="https://termly.io/products/cookie-consent-manager/" target="_blank" rel="noopener" data-v-ed48e36d>Termly&#39;s Cookie Consent Manager</a>. </p>',39)])])}const c=t(r,[["render",i],["__scopeId","data-v-ed48e36d"]]);export{c as default};
